-- Sprint 4 (data-model.md 2-2, 2-8..2-11): milestone types and canned responses (catalog),
-- question threads and messages, weekly check-ins, milestones, student flags and health,
-- plus the attachment foreign keys to question messages and milestones (C4). Generated by
-- drizzle-kit and reviewed.
CREATE TABLE "canned_responses" (
	"id" uuid PRIMARY KEY NOT NULL,
	"title" text NOT NULL,
	"body" text NOT NULL,
	"category" text DEFAULT 'general' NOT NULL,
	"is_active" boolean DEFAULT true NOT NULL,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "canned_responses_category_check" CHECK ("canned_responses"."category" IN ('red_line', 'general'))
);
--> statement-breakpoint
CREATE TABLE "milestone_types" (
	"id" uuid PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"counts_for_north_star" boolean DEFAULT false NOT NULL,
	"unique_per_student" boolean DEFAULT false NOT NULL,
	"requires_evidence" boolean DEFAULT false NOT NULL,
	"sort_order" integer DEFAULT 0 NOT NULL,
	"is_active" boolean DEFAULT true NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE "checkins" (
	"id" uuid PRIMARY KEY NOT NULL,
	"student_id" uuid NOT NULL,
	"week_start" date NOT NULL,
	"activity_text" text,
	"blocker" text,
	"mood" smallint NOT NULL,
	"next_week_plan" text,
	"needs_help" boolean DEFAULT false NOT NULL,
	"question_id" uuid,
	"submitted_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "checkins_mood_check" CHECK ("checkins"."mood" BETWEEN 1 AND 5)
);
--> statement-breakpoint
CREATE TABLE "student_flags" (
	"id" uuid PRIMARY KEY NOT NULL,
	"student_id" uuid NOT NULL,
	"category" text NOT NULL,
	"level" text NOT NULL,
	"note" text,
	"expires_at" timestamp with time zone,
	"cleared_at" timestamp with time zone,
	"cleared_by" uuid,
	"created_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "student_flags_category_check" CHECK ("student_flags"."category" IN ('financial', 'platform_access', 'personal', 'language', 'other')),
	CONSTRAINT "student_flags_level_check" CHECK ("student_flags"."level" IN ('yellow', 'red'))
);
--> statement-breakpoint
CREATE TABLE "student_health" (
	"student_id" uuid PRIMARY KEY NOT NULL,
	"status" text NOT NULL,
	"reasons" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"churn_risk" boolean DEFAULT false NOT NULL,
	"status_since" timestamp with time zone NOT NULL,
	"red_since" timestamp with time zone,
	"computed_at" timestamp with time zone NOT NULL,
	"settings_version" integer DEFAULT 0 NOT NULL,
	"snoozed_until" timestamp with time zone,
	"snooze_reason" text,
	"snoozed_by" uuid,
	CONSTRAINT "student_health_status_check" CHECK ("student_health"."status" IN ('green', 'yellow', 'red', 'paused', 'untracked')),
	CONSTRAINT "student_health_red_since_check" CHECK (("student_health"."status" = 'red') = ("student_health"."red_since" IS NOT NULL))
);
--> statement-breakpoint
CREATE TABLE "milestones" (
	"id" uuid PRIMARY KEY NOT NULL,
	"student_id" uuid NOT NULL,
	"type_id" uuid NOT NULL,
	"occurred_on" date NOT NULL,
	"platform_id" uuid,
	"amount" numeric(12, 2),
	"currency" char(3),
	"evidence_text" text,
	"status" text NOT NULL,
	"proposed_by" uuid NOT NULL,
	"decided_by" uuid,
	"decided_at" timestamp with time zone,
	"rejection_reason" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "milestones_status_check" CHECK ("milestones"."status" IN ('proposed', 'approved', 'rejected')),
	CONSTRAINT "milestones_amount_check" CHECK ("milestones"."amount" IS NULL OR "milestones"."amount" >= 0),
	CONSTRAINT "milestones_rejection_check" CHECK ("milestones"."status" <> 'rejected' OR "milestones"."rejection_reason" IS NOT NULL)
);
--> statement-breakpoint
CREATE TABLE "question_messages" (
	"id" uuid PRIMARY KEY NOT NULL,
	"thread_id" uuid NOT NULL,
	"author_id" uuid NOT NULL,
	"body" text NOT NULL,
	"links" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"canned_response_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"edited_at" timestamp with time zone
);
--> statement-breakpoint
CREATE TABLE "question_threads" (
	"id" uuid PRIMARY KEY NOT NULL,
	"student_id" uuid NOT NULL,
	"subject" text NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"awaiting" text DEFAULT 'team' NOT NULL,
	"awaiting_team_since" timestamp with time zone,
	"assignee_id" uuid NOT NULL,
	"task_id" uuid,
	"priority" text DEFAULT 'normal' NOT NULL,
	"source" text DEFAULT 'student' NOT NULL,
	"first_response_at" timestamp with time zone,
	"last_message_at" timestamp with time zone,
	"closed_at" timestamp with time zone,
	"closed_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "question_threads_status_check" CHECK ("question_threads"."status" IN ('open', 'answered', 'closed')),
	CONSTRAINT "question_threads_awaiting_check" CHECK ("question_threads"."awaiting" IN ('team', 'student', 'none')),
	CONSTRAINT "question_threads_priority_check" CHECK ("question_threads"."priority" IN ('normal', 'urgent')),
	CONSTRAINT "question_threads_source_check" CHECK ("question_threads"."source" IN ('student', 'checkin')),
	CONSTRAINT "question_threads_closed_check" CHECK (("question_threads"."status" = 'closed') = ("question_threads"."closed_at" IS NOT NULL))
);
